import{_ as e,o as r,c as o,a2 as d}from"./chunks/framework.BEUshCVJ.js";const c=JSON.parse('{"title":"模拟面试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/mock-interview.md","filePath":"zh/guide/mock-interview.md","lastUpdated":1793024353000}'),a={name:"zh/guide/mock-interview.md"};function s(n,t,i,l,g,h){return r(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="模拟面试" tabindex="-1">模拟面试 <a class="header-anchor" href="#模拟面试" aria-label="Permalink to &quot;模拟面试&quot;">​</a></h1><p>本页介绍如何一个人从头到尾测试 MeetCue，不需要主持或参加真实会议。MeetCue 会朗读面试问题，通过麦克风听你的回答，并像在会议中一样在面板上显示要点。结束后生成复盘报告。</p><p>第一次模拟面试连同准备工作大约需要 15 分钟。</p><h2 id="一个人测试的三种方式" tabindex="-1">一个人测试的三种方式 <a class="header-anchor" href="#一个人测试的三种方式" aria-label="Permalink to &quot;一个人测试的三种方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>需要密钥</th><th>用到麦克风</th><th>能测试什么</th></tr></thead><tbody><tr><td><a href="/meetcue/zh/quick-start">演示回放</a></td><td>否</td><td>否</td><td>用一段录好的面试看面板的样子和行为</td></tr><tr><td><strong>模拟面试</strong>（本页）</td><td>是</td><td>是</td><td>整个软件：语音识别、问题检测、提示、要点打勾、延迟和复盘</td></tr><tr><td><a href="#meeting-video">用视频测试会议模式</a></td><td>是</td><td>是</td><td>会议模式本身，由一段录好的面试充当对方</td></tr></tbody></table><p>还没有配置任何密钥时，先看演示。其余情况都用模拟面试。</p><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><ol><li><strong>已安装并完成设置。</strong> 你已完成<a href="/meetcue/zh/setup">首次设置</a>，保存并验证了语音识别密钥和模型密钥。没有密钥时，模拟面试可以朗读问题，但不会显示提示。</li><li><strong>戴上耳机。</strong> 模拟面试时，MeetCue 从输出设备播放问题，再通过系统声音听到它们，和会议中听到其他参会者完全一样。用扬声器时麦克风也会收到问题的声音。MeetCue 能过滤大部分回声，但耳机效果最好。</li><li><strong>检查两个电平条。</strong> 打开 <strong>设置 › 音频</strong>，点 <strong>测试电平</strong>，播放任意视频并说几句话。你说话时麦克风电平条应跳动，视频播放时系统声音电平条应跳动。如果有一个不动，请看<a href="/meetcue/zh/troubleshooting/audio">音频与设备</a>。</li><li><strong>注意语言。</strong> 内置的软件工程和安全示例是英文的，SDN 字幕是中文的。默认情况下提示跟随问题的语言；也可以在 <strong>设置 › 通用 › 提示语言</strong> 中固定。</li></ol><h2 id="step-1" tabindex="-1">第 1 步：打开模拟面试窗口 <a class="header-anchor" href="#step-1" aria-label="Permalink to &quot;第 1 步：打开模拟面试窗口 {#step-1}&quot;">​</a></h2><p>以下任意位置都可以打开：</p><ul><li><strong>托盘菜单</strong>：点击任务栏通知区域中的 MeetCue 图标，选择 <strong>模拟面试…</strong>（从上往下第三项）。</li><li><strong>面板</strong>：MeetCue 未在拾取时，面板上的开始提示下方有 <strong>试试模拟面试</strong>。</li><li><strong>设置 › 通用 › 模拟面试</strong>：点 <strong>打开模拟面试</strong>。</li><li><strong>设置向导最后一步</strong>：点 <strong>完成并开始模拟面试</strong>。</li></ul><p>窗口最上方是 <strong>流程</strong>，下面依次是示例面试、自己的文件和历次练习。</p><p>窗口顶部有四个步骤：<strong>声音检查</strong>、<strong>选题目</strong>、<strong>确认</strong> 和 <strong>练习</strong>。每一步结束时都会写明下一步要做什么。</p><h2 id="step-2" tabindex="-1">第 2 步：声音检查与提问的声音 <a class="header-anchor" href="#step-2" aria-label="Permalink to &quot;第 2 步：声音检查与提问的声音 {#step-2}&quot;">​</a></h2><p>第一步会实时显示两条电平。说句话，麦克风电平应当跳动；播放任意视频或点下面的 <strong>试听</strong>，系统声音电平应当跳动。如果有一条始终不动，点 <strong>打开音频设置</strong> 查看设备列表，并参考<a href="/meetcue/zh/troubleshooting/audio">音频与设备</a>。</p><p>在 <strong>提问的声音</strong> 中，按语言各选一个 Windows 语音，点 <strong>试听</strong> 听一句示例。选择 <strong>Windows 提供的第一个语音</strong> 即保持原来的行为。更多语音可在 Windows 设置 › 时间和语言 › 语音 中安装，装好后重启 MeetCue 即可看到。<strong>朗读语速</strong> 也在这一步。</p><h2 id="step-3" tabindex="-1">第 3 步：告诉 MeetCue 你面试的岗位（可选） <a class="header-anchor" href="#step-3" aria-label="Permalink to &quot;第 3 步：告诉 MeetCue 你面试的岗位（可选） {#step-3}&quot;">​</a></h2><p>MeetCue 了解你是谁、面试什么岗位时，提示会更好。这一步只要两分钟，至少值得做一次。</p><ol><li><p>在声音检查这一步点 <strong>打开会前资料</strong>，会打开 <strong>设置 › 提示</strong>。</p></li><li><p>在 <strong>我的角色</strong> 中用一句话描述自己，例如：</p><ul><li><code>后端软件工程师，4 年 Go 和 PostgreSQL 经验</code></li><li><code>正在转向 AI 安全的网络安全工程师，5 年 SOC 经验</code></li></ul></li><li><p>在 <strong>会前资料</strong> 下点 <strong>添加文件…</strong>，选择一份职位描述。有两份示例与内置面试对应：</p><ul><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-software-engineer.md" target="_blank" rel="noreferrer">jd-software-engineer.md</a>：后端软件工程师</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-security-ai.md" target="_blank" rel="noreferrer">jd-security-ai.md</a>：AI 平台团队的网络安全工程师</li></ul><p>在 GitHub 上用 <strong>Download raw file</strong> 按钮下载示例，或者把真实的职位描述粘贴到 <code>.txt</code> 或 <code>.md</code> 文件里。</p></li></ol><p>发送哪些内容、如何保持精简，见<a href="/meetcue/zh/guide/materials">会前资料</a>。如果不想在真实会议中用到这份职位描述，练习后删除即可。</p><h2 id="step-4" tabindex="-1">第 4 步：选择面试 <a class="header-anchor" href="#step-4" aria-label="Permalink to &quot;第 4 步：选择面试 {#step-4}&quot;">​</a></h2><p>在 <strong>试试示例面试</strong> 下，点某个内置面试旁边的 <strong>使用</strong>，不需要下载任何文件。</p><table tabindex="0"><thead><tr><th>示例</th><th>类型</th><th>会发生什么</th></tr></thead><tbody><tr><td>软件工程师：问题列表</td><td>14 道题</td><td>基础知识、算法、系统设计、排障、数据库、分布式系统和团队协作，一次一题</td></tr><tr><td>软件工程师：面试字幕</td><td>回答 6 次</td><td>一场后端工程师技术面。朗读面试官的话，轮到你时停下来</td></tr><tr><td>网络安全与 AI：问题列表</td><td>12 道题</td><td>TLS、零信任、横向移动、DNS 外泄、机器学习入侵检测、提示词注入、RAG 安全、AI 治理</td></tr><tr><td>网络安全与 AI：面试字幕</td><td>回答 5 次</td><td>一场 AI 平台团队的安全工程师面试</td></tr><tr><td>网络架构：问题列表</td><td>10 道题</td><td>路由、数据中心网络和 SDN</td></tr><tr><td>SDN 面试字幕（中文）</td><td>回答 3 次</td><td>一段简短的中文面试</td></tr></tbody></table><p><strong>先用哪个？</strong> 第一次建议用 <strong>问题列表</strong>：MeetCue 提一个问题，等你回答，你停顿后进入下一题，便于逐项确认每个环节都在工作。想演练真实对话的节奏（包括寒暄和中间的追问），再用 <strong>面试字幕</strong>。</p><p>每个示例的每道题都带参考回答，复盘时能指出你漏掉了什么。如果想修改，同样的文件在仓库的 <a href="https://github.com/Amazingkenneth/meetcue/tree/HEAD/samples/practice" target="_blank" rel="noreferrer">samples/practice</a> 目录下。</p><p>要用自己的题目，在 <strong>使用自己的文件</strong> 下点 <strong>选择文件…</strong>，见<a href="#own-interview">编写自己的面试</a>。</p><h2 id="step-5" tabindex="-1">第 5 步：检查题目 <a class="header-anchor" href="#step-5" aria-label="Permalink to &quot;第 5 步：检查题目 {#step-5}&quot;">​</a></h2><p>预览表列出每道题或每句话。你可以：</p><ul><li>点击题目直接修改文字。</li><li>上移、下移或删除题目。</li><li>问题列表：<strong>随机打乱</strong>，或 <strong>只保留前</strong> 几道，例如只练 5 道题。</li><li>面试字幕：检查 <strong>哪个说话人是你？</strong> MeetCue 会选提问最少的说话人，示例中就是 <strong>Candidate</strong>。你的句子不会被朗读，而是作为参考回答。</li></ul><h2 id="step-6" tabindex="-1">第 6 步：选择练习方式 <a class="header-anchor" href="#step-6" aria-label="Permalink to &quot;第 6 步：选择练习方式 {#step-6}&quot;">​</a></h2><p>模拟面试与真实会议一致：每道题都会朗读出来，以声音的形式传给 MeetCue，前两个开关决定是否由语音识别供应商转成文字。想测试整个软件就两个都开；想更省钱地准备面试，可以关闭 <strong>问题语音转文字</strong>。</p><p>第一次模拟面试建议这样设置：</p><table tabindex="0"><thead><tr><th>选项</th><th>第一次</th><th>原因</th></tr></thead><tbody><tr><td>问题语音转文字</td><td>开启</td><td>朗读的问题从系统声音采集，由语音识别供应商转成文字，与会议完全一致</td></tr><tr><td>提示难度</td><td><strong>完整</strong></td><td>显示面板能显示的所有内容</td></tr><tr><td>停顿多久算答完</td><td>3 秒</td><td>如果你思考时被打断，调到 4 或 5 秒</td></tr><tr><td>追问</td><td>开启</td><td>检验 MeetCue 能否针对你实际说的话作出反应</td></tr><tr><td>我的回答语音转文字</td><td>开启</td><td>要点打勾和大部分复盘指标需要它</td></tr><tr><td>我开口时停止朗读</td><td>开启</td><td>像真实对话一样可以打断</td></tr></tbody></table><p>然后点 <strong>开始练习</strong>。如果面板之前是隐藏的，它会显示出来。</p><h2 id="step-7" tabindex="-1">第 7 步：出声回答 <a class="header-anchor" href="#step-7" aria-label="Permalink to &quot;第 7 步：出声回答 {#step-7}&quot;">​</a></h2><p>每道题的过程如下：</p><ol><li><strong>MeetCue 用 Windows 语音朗读问题。</strong> 练习窗口显示“正在朗读问题”。朗读时开口说话会停止朗读。</li><li><strong>面板显示提示。</strong> 问题结束后约一秒半，面板上出现灰色的问题和三到五条带编号的要点，每条都有加粗的主词。</li><li><strong>出声回答</strong>，就像面试官在听一样。把要点当作提示，而不是照着念。</li><li><strong>要点自动打勾。</strong> 讲到的要点会打勾，下一条未讲的要点标为 <strong>接下来</strong>。</li><li><strong>停顿即答完。</strong> 停顿达到你设置的时长（默认 3 秒）后，MeetCue 有时会追问，然后进入下一题。20 秒内没有开口，面板会轻提示。</li></ol><p>练习窗口和面板都会显示当前该做什么，并且都有 <strong>再问一遍</strong>：从头重读当前这道题。没听清，或者想把同一道题再答一次时可以用它；已经开始的回答会被丢弃，也不会额外调用模型。</p><p>你开口回答时 MeetCue 会停止朗读，但只针对真正的说话：咳嗽、“嗯”，或者把问题本身听错的一两个词都不会把问题打断。也可以在练习选项中关闭 <strong>我开口时停止朗读</strong>。</p><p>以下快捷键在其他窗口有焦点时也有效：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+Enter</code></td><td>我答完了</td></tr><tr><td><code>Ctrl+Alt+]</code></td><td>跳过这道题</td></tr><tr><td><code>Ctrl+Alt+Space</code></td><td>暂停或继续</td></tr><tr><td><code>Ctrl+Alt+H</code></td><td>面板：完整 → 迷你条 → 隐藏</td></tr></tbody></table><p>练习窗口里也有对应按钮，另外还有 <strong>结束练习</strong>。</p><h2 id="step-8" tabindex="-1">第 8 步：查看复盘 <a class="header-anchor" href="#step-8" aria-label="Permalink to &quot;第 8 步：查看复盘 {#step-8}&quot;">​</a></h2><p>最后一题结束后，或点 <strong>结束练习</strong> 后，复盘会在单独的窗口中打开。它按题目和整场显示反应时间、回答时长、要点覆盖、口头禅、语速，以及对照参考回答的三条简短点评。各项含义见<a href="/meetcue/zh/guide/practice#review-report">复盘报告</a>。</p><p>点 <strong>导出 Markdown</strong> 保存报告。历次练习保存在模拟面试窗口的 <strong>历次练习</strong> 中。</p><h2 id="self-test-plan" tabindex="-1">完整自测方案 <a class="header-anchor" href="#self-test-plan" aria-label="Permalink to &quot;完整自测方案 {#self-test-plan}&quot;">​</a></h2><p>按下面五轮练习，每轮测试一项功能，就能覆盖 MeetCue 的全部功能。每轮约五分钟。</p><table tabindex="0"><thead><tr><th>轮次</th><th>示例</th><th>设置</th><th>检查</th></tr></thead><tbody><tr><td>1</td><td>软件工程师：问题列表，只保留前 5 道</td><td>语音转文字开启，完整</td><td>每道题都被朗读，提示出现，说话时要点打勾，复盘自动打开</td></tr><tr><td>2</td><td>网络安全与 AI：问题列表，只保留前 5 道</td><td>语音转文字开启，只显示主词，并添加安全岗位的职位描述</td><td>提示提到岗位相关内容（零信任、检测、大模型安全）；只显示主词</td></tr><tr><td>3</td><td>软件工程师：面试字幕</td><td>语音转文字开启，完整</td><td>轮到你时停下等待；寒暄通常不出提示；复盘把你的回答与候选人的原话对比</td></tr><tr><td>4</td><td>网络安全与 AI：面试字幕</td><td>问题语音转文字关闭，延迟显示（5 秒）</td><td>每道题结束约 5 秒后出现提示；复盘注明识别延迟为模拟值</td></tr><tr><td>5</td><td>任意问题列表</td><td>语音转文字开启，提示关闭</td><td>练习时不显示提示，回答后仍能在复盘中得到点评</td></tr></tbody></table><p>第 1 轮结束后看看面板底部的延迟。一秒半左右是正常的；明显更高说明供应商或网络较慢，见<a href="/meetcue/zh/troubleshooting/latency">延迟偏高</a>。</p><h2 id="meeting-video" tabindex="-1">用视频测试会议模式 <a class="header-anchor" href="#meeting-video" aria-label="Permalink to &quot;用视频测试会议模式 {#meeting-video}&quot;">​</a></h2><p>模拟面试和会议走的是同一条链路，只是节奏由 MeetCue 控制。要测试会议模式本身，可以让一段录像来扮演面试官：</p><ol><li>戴上耳机。</li><li>打开一段录好的模拟面试，例如视频网站上的技术面试视频，先暂停在开头。</li><li>按 <code>Ctrl+Alt+Space</code> 开始拾取，状态点变绿。</li><li>播放视频。面试官提问时，会出现带要点的问题块。</li><li>暂停视频并出声回答，观察要点打勾。继续播放进入下一个问题。</li><li>再按 <code>Ctrl+Alt+Space</code> 停止。</li></ol><p>从输出设备播放的任何声音都算作对方，所以录好的通话录音、或者用文字转语音网站读出的问题也同样可以。</p><h2 id="own-interview" tabindex="-1">编写自己的面试 <a class="header-anchor" href="#own-interview" aria-label="Permalink to &quot;编写自己的面试 {#own-interview}&quot;">​</a></h2><p>最快的格式是每道题都带参考回答的 CSV 文件，只有 <code>question</code> 列是必填的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>question,reference_answer,category,followups</span></span>
<span class="line"><span>&quot;哈希表如何处理冲突？&quot;,&quot;拉链法或开放寻址；负载因子超过阈值时扩容；好的哈希函数让链保持很短。&quot;,数据结构,&quot;最坏情况下查找的时间复杂度是多少？&quot;</span></span>
<span class="line"><span>&quot;如何发现 API 密钥被盗用？&quot;,&quot;对来自新地点或新网络、调用量或接口异常的使用发出告警；定期轮换密钥；按最小权限限定密钥范围。&quot;,安全,</span></span></code></pre></div><p>多个追问用 <code>|</code> 分隔。问题列表也可以是每行一题的纯文本或 Markdown，面试字幕可以是 <code>.srt</code>、<code>.vtt</code> 或 <code>.txt</code>。所有格式见<a href="/meetcue/zh/reference/file-formats">文件格式</a>。</p><p>要把职位描述变成问题列表，可以让任意聊天助手来写：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据下面的职位描述写 12 道技术面试题，输出为 CSV 文件，列为 question、reference_answer、</span></span>
<span class="line"><span>category 和 followups。每个参考回答控制在两三句话。多个追问用 | 分隔。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;粘贴职位描述&gt;</span></span></code></pre></div><p>练习前请先检查题目和答案。</p><h2 id="troubleshooting" tabindex="-1">遇到问题 <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;遇到问题 {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因和解决方法</th></tr></thead><tbody><tr><td>问题被朗读了，但没有提示</td><td>密钥或模型有问题。面板会显示错误码，点 <strong>查看解决办法</strong>。在 <strong>设置 › 供应商与费用</strong> 中用 <strong>验证</strong> 检查密钥</td></tr><tr><td>开启问题语音转文字时没有提示，关闭后有提示</td><td>MeetCue 听不到系统声音。检查系统声音电平条，见<a href="/meetcue/zh/troubleshooting/audio">音频与设备</a></td></tr><tr><td>要点从不打勾</td><td><strong>我的回答语音转文字</strong> 已关闭，或者麦克风电平条不动。检查 <strong>设置 › 音频</strong></td></tr><tr><td>朗读问题时要点就打勾了</td><td>麦克风收到了扬声器的声音。请戴耳机，见<a href="/meetcue/zh/troubleshooting/audio#echo">回声</a></td></tr><tr><td>还在思考时就进入下一题</td><td>把 <strong>停顿多久算答完</strong> 调到 4 或 5 秒</td></tr><tr><td>朗读太快或太慢</td><td>在声音检查这一步调整 <strong>朗读语速</strong></td></tr><tr><td>问题读到一半就停了</td><td>有声音把它打断了。点 <strong>再问一遍</strong>，戴上耳机；如果仍然如此，关闭 <strong>我开口时停止朗读</strong></td></tr><tr><td>语音不对或不好听</td><td>在 <strong>提问的声音</strong> 中换一个，并点 <strong>试听</strong></td></tr><tr><td>没有可选的语音</td><td>Windows 没有安装语音。请在 Windows 设置 › 时间和语言 › 语音 中添加，然后重启 MeetCue</td></tr><tr><td>提示太笼统</td><td>添加 <strong>我的角色</strong> 和职位描述，见<a href="#step-2">第 2 步</a></td></tr></tbody></table><p>两个语音转文字开关都开启时，模拟面试和会议一样使用语音识别和模型供应商，费用与同样时长的会议差不多。关闭 <strong>问题语音转文字</strong> 可省去问题的识别费用，问题仍会朗读出来；再关闭 <strong>我的回答语音转文字</strong> 则完全不产生识别费用。</p>`,63)])])}const u=e(a,[["render",s]]);export{c as __pageData,u as default};
